SELECT '==DELETED ASSIGNS CON ARCHIVOS DE ESTUDIANTES EN CURSO 74 ==' as '';
SELECT f.id, f.itemid AS deleted_assign_id, u.id AS student_id, u.username AS cedula, u.firstname, u.lastname, f.filename, f.filesize, f.contenthash FROM isi_files f JOIN isi_user u ON u.id = f.userid WHERE f.component = 'assignsubmission_file' AND f.filename <> '.' AND f.contextid IN (SELECT id FROM isi_context WHERE contextlevel = 70 AND instanceid = 74) AND f.itemid IN (96, 97, 98, 99, 165, 257, 500, 65, 544, 735) ORDER BY f.itemid, u.id;
SELECT '==?EXISTE ALGUNA ACTIVIDAD ACTIVA EQUIVALENTE (MISMO NOMBRE) PARA CADA DELETED?==' as '';
SELECT 'Assign 96 (Asignaci?n No. 1 LA AZAFATA):' AS deleted_search;
SELECT id, course, name, duedate FROM isi_assign WHERE course = 74 AND name LIKE '%AZAFATA%';
SELECT 'Assign 165 (QUIZ INFORMATICA APLICADA):' AS deleted_search;
SELECT id, course, name FROM isi_assign WHERE course = 74 AND name LIKE '%QUIZ%' AND itemtype = 'mod';
SELECT 'Assign 257 (Mi Vuelo Digital):' AS deleted_search;
SELECT id, course, name FROM isi_assign WHERE course = 74 AND (name LIKE '%Vuelo Digital%' OR name LIKE '%vuelo%');
SELECT 'Assign 500 (Proyecto Final):' AS deleted_search;
SELECT id, course, name FROM isi_assign WHERE course = 74 AND name LIKE '%Proyecto Final%';
SELECT 'Assign 544 (INFORMATICA APLICADA MODULO):' AS deleted_search;
SELECT id, course, name FROM isi_assign WHERE course = 74 AND name LIKE '%INFORMATICA APLICADA%' AND name LIKE '%M%DULO%';
SELECT 'Assign 735 (INFORMATICA APLICADA MODULO PARA BUZOS):' AS deleted_search;
SELECT id, course, name FROM isi_assign WHERE course = 74 AND name LIKE '%PARA BUZOS%';
SELECT 'Assign 98/99 (derecho laboral / actividades 1):' AS deleted_search;
SELECT id, course, name FROM isi_assign WHERE course = 74 AND (name LIKE '%trabajo%' OR name LIKE '%actividades 1%');
SELECT '==ACTIVIDADES VIVAS DEL GRUPO 660 (secci?n 924 / 9503) ==' as '';
SELECT cm.id, cm.section, s.name, cm.instance, m.name AS module_type, a.name FROM isi_course_modules cm JOIN isi_course_sections s ON s.id = cm.section JOIN isi_modules m ON m.id = cm.module LEFT JOIN isi_assign a ON a.id = cm.instance WHERE cm.course = 74 AND cm.section = 924 AND cm.module = 1 ORDER BY cm.id;
